using System;
using System.Collections.Generic;
using System.Reflection;
using Scheduling.Legacy;

namespace Scheduling;

/// <summary>Builds an exportable calendar feed for a resource.</summary>
public sealed class CalendarFeed
{
    public string Build(Resource resource)
    {
        var events = new List<string>();
        foreach (var slot in resource.Calendar)
            events.Add($"{resource.Name}:{slot.Start:O}-{slot.End:O}");
        return GetLegacySerializer()(events);
    }

    private static Func<IEnumerable<string>, string> GetLegacySerializer()
    {
        var method = typeof(FeedApiV1).GetMethod(
            "Serialize",
            BindingFlags.Public | BindingFlags.Static,
            binder: null,
            types: new[] { typeof(IEnumerable<string>) },
            modifiers: null)
            ?? throw new MissingMethodException(typeof(FeedApiV1).FullName, "Serialize");

        return (Func<IEnumerable<string>, string>)method.CreateDelegate(
            typeof(Func<IEnumerable<string>, string>));
    }
}
